    /// Mirrors mudclient.loadEntitiesAuthentic — assigns sprite-archive offsets.
    /// Each unique animation name consumes 27 sprite slots (15 walk + 3 combat A + 9 combat F).
    /// Range 1998..<3300 is reserved for UI sprites and is skipped.
    static func assignNumbers() {
        var animationNumber = 0
        var nameToNumber: [String: Int] = [:]
        for i in 0..<entries.count {
            let key = entries[i].name.lowercased()
            if let existing = nameToNumber[key] {
                entries[i].number = existing
                continue
            }
            entries[i].number = animationNumber
            nameToNumber[key] = animationNumber
            animationNumber += 27
            if animationNumber == 1998 {
                animationNumber = 3300
            }
        }
    }

    static func get(_ index: Int) -> AnimationData? {
        guard index >= 0 && index < entries.count else { return nil }
        return entries[index]
    }
